 import unittest
from candidate import will_it_fly

class TestWillItFly(unittest.TestCase):
    def test_will_it_fly_normalcase_balanced_less_than_weight(self):
        self.assertTrue(will_it_fly([3, 2, 3], 9))

    def test_will_it_fly_normalcase_unbalanced(self):
        self.assertFalse(will_it_fly([1, 2], 5))

    def test_will_it_fly_normalcase_greater_than_weight(self):
        self.assertFalse(will_it_fly([3, 2, 3], 1))

    def test_will_it_fly_normalcase_single_element(self):
        self.assertTrue(will_it_fly([3], 5))

    def test_will_it_fly_empty_list(self):
        self.assertIsNone(will_it_fly([], 5))

    def test_will_it_fly_negative_numbers(self):
        self.assertFalse(will_it_fly([-1, 2], 5))

    def test_will_it_fly_float_numbers(self):
        self.assertAlmostEqual(will_it_fly([2.5, 1.5], 4), True)
        self.assertAlmostEqual(will_it_fly([2.5, 1.5], 5), False)

    def test_will_it_fly_mixed_numbers(self):
        self.assertFalse(will_it_fly([1, 2, 3], 1))
        self.assertTrue(will_it_fly([1, 2, 3], 5))

    def test_will_it_fly_large_list(self):
        self.assertTrue(will_it_fly([1, 2, 3, 4, 5], 15))

    def test_will_it_fly_max_weight(self):
        self.assertTrue(will_it_fly([1, 2, 3, 4, 5], 60))

    def test_will_it_fly_max_weight_unbalanced(self):
        self.assertFalse(will_it_fly([1, 2, 3, 2, 1], 60))

if __name__ == '__main__':
    unittest.main()
